@layer base {
  /* Soft lift. The brand colour is only on the primary button; secondary,
     outline and ghost are neutral. Primary, destructive and outline sit on a
     soft 1px shadow that grows a little on hover and drops away when pressed.
     Heights 32 / 36 / 44px line up with Input, Select and Toggle. */
  .button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    font-family: var(--font-family-base);
    font-size: 0.875rem;
    font-weight: 500;
    line-height: 1;
    border-radius: var(--radius);
    white-space: nowrap;
    text-decoration: none;
    cursor: pointer;
    user-select: none;
    transition:
      background-color var(--animation-duration-fast) ease,
      border-color var(--animation-duration-fast) ease,
      color var(--animation-duration-fast) ease,
      box-shadow var(--animation-duration-fast) ease;
    outline: none;
    border: 1px solid transparent;
    position: relative;
  }

  /* Keyboard focus: a soft neutral halo, the same on every small control. */
  .button:focus-visible {
    box-shadow: 0 0 0 4px color-mix(in srgb, var(--foreground) 9%, transparent);
    outline: none;
  }

  /* Sizes */
  .sm {
    height: 2rem;
    padding: 0 10px;
    font-size: 0.8125rem;
  }

  .md {
    height: 2.25rem;
    padding: 0 14px;
  }

  .lg {
    height: 2.75rem;
    padding: 0 18px;
    font-size: 0.9375rem;
    border-radius: var(--radius-md);
  }

  .icon,
  .icon-md {
    width: 2.25rem;
    height: 2.25rem;
    padding: 0;
  }

  .icon-sm {
    width: 2rem;
    height: 2rem;
    padding: 0;
  }

  .icon-lg {
    width: 2.75rem;
    height: 2.75rem;
    padding: 0;
    border-radius: var(--radius-md);
  }

  /* shape="pill": fully rounded, a little more room at the sides. */
  .pill {
    border-radius: 9999px;
  }

  .pill.sm {
    padding: 0 12px;
  }

  .pill.md {
    padding: 0 16px;
  }

  .pill.lg {
    padding: 0 22px;
  }

  /* Icons */
  .button svg {
    flex-shrink: 0;
    width: 1rem;
    height: 1rem;
  }

  .sm svg,
  .icon-sm svg {
    width: 0.875rem;
    height: 0.875rem;
  }

  .lg svg,
  .icon-lg svg {
    width: 1.125rem;
    height: 1.125rem;
  }

  /* Primary: the one brand-coloured button. */
  .primary {
    background-color: var(--primary);
    color: var(--primary-foreground);
    border-color: var(--primary);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.14);
    --spinner-color: var(--primary-foreground);
  }

  .primary:hover {
    background-color: color-mix(in oklch, var(--primary) 88%, black);
    border-color: color-mix(in oklch, var(--primary) 88%, black);
    box-shadow: 0 2px 6px -1px rgb(0 0 0 / 0.2);
  }

  .primary:active {
    background-color: color-mix(in oklch, var(--primary) 80%, black);
    border-color: color-mix(in oklch, var(--primary) 80%, black);
    box-shadow: none;
  }

  /* Secondary: a neutral tinted button, no border. */
  .secondary {
    background-color: color-mix(in srgb, var(--foreground) 6%, transparent);
    color: var(--foreground);
    --spinner-color: var(--foreground);
  }

  .secondary:hover {
    background-color: color-mix(in srgb, var(--foreground) 10%, transparent);
  }

  .secondary:active {
    background-color: color-mix(in srgb, var(--foreground) 13%, transparent);
  }

  /* Destructive: solid error colour, lifted like primary. */
  .destructive {
    background-color: var(--error);
    color: var(--error-foreground);
    border-color: var(--error);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.14);
    --spinner-color: var(--error-foreground);
  }

  .destructive:hover {
    background-color: color-mix(in oklch, var(--error) 88%, black);
    border-color: color-mix(in oklch, var(--error) 88%, black);
    box-shadow: 0 2px 6px -1px rgb(0 0 0 / 0.2);
  }

  .destructive:active {
    background-color: color-mix(in oklch, var(--error) 80%, black);
    border-color: color-mix(in oklch, var(--error) 80%, black);
    box-shadow: none;
  }

  /* Outline: text-colour label on the card, a hairline border, slightly
     raised. The secondary action next to a primary button, and menu triggers. */
  .outline {
    background-color: var(--card);
    border-color: color-mix(in srgb, var(--foreground) 12%, transparent);
    color: var(--foreground);
    box-shadow: 0 1px 2px rgb(0 0 0 / 0.05);
    --spinner-color: var(--foreground);
  }

  .outline:hover,
  .outline[data-state="open"] {
    background-color: color-mix(in srgb, var(--foreground) 4%, var(--card));
    border-color: color-mix(in srgb, var(--foreground) 22%, transparent);
    box-shadow: 0 2px 6px -2px rgb(0 0 0 / 0.14);
  }

  .outline:active {
    background-color: color-mix(in srgb, var(--foreground) 7%, var(--card));
    box-shadow: none;
  }

  /* Ghost: no surface until hovered. */
  .ghost {
    background-color: transparent;
    color: var(--foreground);
    --spinner-color: var(--foreground);
  }

  .ghost:hover {
    background-color: color-mix(in srgb, var(--foreground) 6%, transparent);
  }

  .ghost:active {
    background-color: color-mix(in srgb, var(--foreground) 9%, transparent);
  }

  /* Link: brand-coloured text, underline on hover. */
  .link {
    height: auto;
    padding: 0;
    border: none;
    border-radius: var(--radius-sm);
    background-color: transparent;
    color: var(--primary);
    text-underline-offset: 3px;
    --spinner-color: var(--primary);
  }

  .link:hover {
    text-decoration: underline;
  }

  /* Focus keeps the lifted buttons' own shadow under the halo. */
  .primary:focus-visible,
  .outline:focus-visible {
    box-shadow:
      0 1px 2px rgb(0 0 0 / 0.08),
      0 0 0 4px color-mix(in srgb, var(--foreground) 9%, transparent);
  }

  .destructive:focus-visible {
    box-shadow:
      0 1px 2px rgb(0 0 0 / 0.08),
      0 0 0 4px color-mix(in srgb, var(--error) 18%, transparent);
  }

  /* Disabled */
  .disabled,
  .button:disabled {
    opacity: 0.45;
    cursor: not-allowed;
    pointer-events: none;
    box-shadow: none;
  }
}

